from itertools import groupby

def sum_by_category(transactions: list[dict]) -> dict[str, int]:
    # КРИТИЧНО: groupby группирует только соседние элементы, поэтому сначала сортируем!
    key_fn = lambda tx: tx["category"]
    sorted_tx = sorted(transactions, key=key_fn)
    return {
        category: sum(item["amount"] for item in group)
        for category, group in groupby(sorted_tx, key=key_fn)
    }

