from collections import deque

class CommandQueue:
    def __init__(self):
        self._q: deque[str] = deque()

    def enqueue(self, cmd: str) -> None:
        self._q.append(cmd)

    def prepend_urgent(self, cmd: str) -> None:
        self._q.appendleft(cmd)

    def dequeue(self) -> str | None:
        return self._q.popleft() if self._q else None

    def drain(self, n: int) -> list[str]:
        if n <= 0:
            return []
        count = min(n, len(self._q))
        return [self._q.popleft() for _ in range(count)]

