from collections import deque, ChainMap, Counter

def moving_average(values: list[float], window: int) -> list[float]:
    if window <= 0:
        raise ValueError('window must be positive')
    buf: deque[float] = deque(maxlen=window)
    result: list[float] = []
    for v in values:
        buf.append(v)
        result.append(sum(buf) / len(buf))
    return result

def resolve_config(cli: dict, env: dict, defaults: dict) -> dict:
    return dict(ChainMap(cli, env, defaults))

def top_k_words(words: list[str], k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []
    return Counter(words).most_common(k)

