solution:
from functools import wraps

def limit_calls(_func=None, *, limit: int = 3):
    def decorator(fn):
        calls = 0
        @wraps(fn)
        def wrapper(*args, **kwargs):
            nonlocal calls
            if calls >= limit:
                raise RuntimeError('Call limit exceeded')
            calls += 1
            return fn(*args, **kwargs)
        return wrapper
    if _func is not None:
        return decorator(_func)
    return decorator

tests:
@limit_calls
def ping():
    return 'pong'
assert ping() == 'pong' and ping() == 'pong' and ping() == 'pong'
try:
    ping()
    assert False
except RuntimeError:
    pass
@limit_calls(limit=1)
def greet(name):
    return f'hi {name}'
assert greet('Ann') == 'hi Ann' and greet.__name__ == 'greet'
try:
    greet('Bob')
    assert False
except RuntimeError:
    pass
class Worker:
    @limit_calls(limit=2)
    def run(self, x):
        return x * 2
w = Worker()
