import io

def read_until_eof(reader_fn, eof_marker: str = '') -> list[str]:
    return list(iter(reader_fn, eof_marker))

def count_chunks_in_stream(stream: io.StringIO, chunk_size: int) -> tuple[list[str], int]:
    if chunk_size <= 0:
        raise ValueError('chunk_size must be positive')
    chunks = list(iter(lambda: stream.read(chunk_size), ''))
    total_chars = sum(len(c) for c in chunks)
    return chunks, total_chars

