from itertools import groupby, tee

def group_users_by_role(users: list[dict]) -> dict[str, list[str]]:
    key_fn = lambda u: u['role']
    ordered = sorted(users, key=key_fn)
    return {role: [u['name'] for u in group] for role, group in groupby(ordered, key=key_fn)}

def split_min_max(stream) -> tuple[int, int]:
    it1, it2 = tee(stream, 2)
    return min(it1), max(it2)

tests:
users = [
    {'name': 'Alice', 'role': 'dev'},
    {'name': 'Bob', 'role': 'qa'},
    {'name': 'Charlie', 'role': 'dev'},
]
assert group_users_by_role(users) == {'dev': ['Alice', 'Charlie'], 'qa': ['Bob']}
assert group_users_by_role([{'name': 'Z', 'role': 'ops'}]) == {'ops': ['Z']}
assert group_users_by_role([]) == {}
gen = (x for x in [5, 1, 9, 3])
assert split_min_max(gen) == (1, 9)
assert split_min_max(iter([-10, -2, -50])) == (-50, -2)
assert split_min_max(iter([42])) == (42, 42)

