def running_avg(log: list[str]):
    total = 0.0
    count = 0
    avg = 0.0
    try:
        while True:
            try:
                val = yield avg
                total += val
                count += 1
                avg = total / count
            except ValueError:
                total = 0.0
                count = 0
                avg = 0.0
    finally:
        log.append('closed')

def collect_subgen(sub):
    collected = []
    def _wrapper():
        res = yield from sub
        return res
    gen = _wrapper()
    try:
        while True:
            collected.append(next(gen))
    except StopIteration as exc:
        return collected, exc.value

