class SafeTransaction:
    def __init__(self, store: dict, ignore_exc=None):
        self.store = store
        self.ignore_exc = ignore_exc
        self._snapshot = None

    def __enter__(self):
        self._snapshot = dict(self.store)
        return self.store

    def __exit__(self, exc_type, exc_val, exc_tb):
        if exc_type is None:
            return False
        self.store.clear()
        self.store.update(self._snapshot)
        if self.ignore_exc is not None and issubclass(exc_type, self.ignore_exc):
            return True
        return False

