from contextlib import contextmanager, ExitStack

@contextmanager
def managed_resource(name: str, log: list[str]):
    log.append(f'open:{name}')
    try:
        yield name
    finally:
        log.append(f'close:{name}')

def open_all_lifo(names: list[str], log: list[str]) -> list[str]:
    with ExitStack() as stack:
        return [stack.enter_context(managed_resource(n, log)) for n in names]

